original_runtime_probe.probe_source:
extends Node3D

func _ready() -> void:
	var args := OS.get_cmdline_user_args()
	if args.size() != 2:
		push_error("Expected glTF and output paths")
		get_tree().quit(1)
		return
	var document := GLTFDocument.new()
	var state := GLTFState.new()
	var error := document.append_from_file(args[0], state, GLTFDocument.IMPORT_FLAG_GENERATE_TANGENT_ARRAYS)
	if error != OK:
		push_error("GLTF probe load failed: %s" % error)
		get_tree().quit(1)
		return
	var images: Array = []
	var texture_ids: Dictionary = {}
	for index in state.get_images().size():
		var texture: Texture2D = state.get_images()[index]
		if texture == null:
			push_error("Missing source texture")
			get_tree().quit(1)
			return
		texture_ids[texture.get_instance_id()] = index
		var image := texture.get_image()
		if image == null or image.is_empty():
			push_error("Cannot read actual texture image")
			get_tree().quit(1)
			return
		images.append({"index": index, "class": texture.get_class(), "width": image.get_width(), "height": image.get_height(),
			"format": image.get_format(), "compressed": image.is_compressed(), "has_mipmaps": image.has_mipmaps(),
			"mipmap_count": image.get_mipmap_count(), "data_bytes": image.get_data().size()})
	var references: Array = []
	var roles := {"albedo": BaseMaterial3D.TEXTURE_ALBEDO, "normal": BaseMaterial3D.TEXTURE_NORMAL,
		"metallic": BaseMaterial3D.TEXTURE_METALLIC, "roughness": BaseMaterial3D.TEXTURE_ROUGHNESS,
		"emission": BaseMaterial3D.TEXTURE_EMISSION, "ao": BaseMaterial3D.TEXTURE_AMBIENT_OCCLUSION}
	for index in state.get_materials().size():
		var material: StandardMaterial3D = state.get_materials()[index]
		for role in roles:
			var texture: Texture2D = material.get_texture(roles[role])
			if texture != null:
				references.append({"material": index, "role": role, "image": texture_ids.get(texture.get_instance_id(), -1), "class": texture.get_class()})
	var result := {"version": Engine.get_version_info(), "editor": OS.has_feature("editor"), "debug": OS.has_feature("debug"),
		"driver": RenderingServer.get_current_rendering_driver_name(), "method": RenderingServer.get_current_rendering_method(),
		"images": images, "material_references": references}
	FileAccess.open(args[1], FileAccess.WRITE).store_string(JSON.stringify(result, "\t", false, true) + "\n")
	print("PROBE images=", images.size(), " references=", references.size())
	get_tree().quit(0)

