extends Node3D
const MaterialMips = preload("res://material_mips.gd")

func require(condition: bool, message: String) -> bool:
	if not condition:
		push_error(message)
		get_tree().quit(1)
	return condition

func _ready() -> void:
	if not require(not OS.has_feature("editor") and not OS.has_feature("debug"), "Release template required"):
		return
	var args := OS.get_cmdline_user_args()
	if not require(args.size() == 1, "Expected output JSON path"):
		return
	var color := Image.create(2, 2, false, Image.FORMAT_RGBA8)
	color.fill(Color(0.2, 0.4, 0.6))
	var normal := Image.create(4, 4, false, Image.FORMAT_RGBA8)
	normal.fill(Color(0.7, 0.7, 0.7))
	var pixel := Image.create(1, 1, false, Image.FORMAT_RGBA8)
	pixel.fill(Color(0.1, 0.3, 0.5, 0.7))
	var images: Array[Texture2D] = [ImageTexture.create_from_image(color), ImageTexture.create_from_image(normal), ImageTexture.create_from_image(pixel)]
	var material := StandardMaterial3D.new()
	material.texture_filter = BaseMaterial3D.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS
	material.albedo_texture = images[0]
	material.normal_texture = images[1]
	material.metallic_texture = images[0]
	material.roughness_texture = images[0]
	material.ao_texture = images[0]
	material.emission_texture = images[2]
	var materials: Array[Material] = [material]
	var before := normal.get_data().slice(0, 4)
	var proof := MaterialMips.prepare(images, materials)
	if not require(not proof.has("error"), "Small preparation failed: %s" % proof):
		return
	if not require(proof.total_levels_including_base == 6 and proof.normal_images == 1, "Small mip totals differ"):
		return
	if not require(proof.images[2].mipmap_count == 0 and proof.images[2].has_mipmaps == false, "1x1 native chain differs"):
		return
	var native_normal := images[1].get_image().get_data()
	if not require(native_normal.slice(64, 68) != before, "Normal coarse mip was not renormalized"):
		return
	material.texture_filter = BaseMaterial3D.TEXTURE_FILTER_LINEAR
	var bad_filter := MaterialMips.prepare(images, materials)
	if not require(bad_filter.has("error"), "Missing mip filtering was accepted"):
		return
	material.texture_filter = BaseMaterial3D.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS
	material.normal_texture = images[0]
	var mixed := MaterialMips.prepare(images, materials)
	if not require(mixed.has("error"), "Mixed normal/color semantics were accepted"):
		return
	proof.normal_coarse_mip_changed = true
	proof.filter_fault_rejected = true
	proof.mixed_semantic_fault_rejected = true
	proof.godot = Engine.get_version_info()
	proof.driver = RenderingServer.get_current_rendering_driver_name()
	proof.renderer = RenderingServer.get_current_rendering_method()
	FileAccess.open(args[0], FileAccess.WRITE).store_string(JSON.stringify(proof, "\t", false, true) + "\n")
	print("SMALL_MIPS_PASS")
	get_tree().quit(0)
